// Berechnet wpTags fuer die Ziel-Posts genau wie "Baue Post-Body" in
// ALLRIS_P8_Partei_Webseite (gleiche topicTagsFromText()-Kategorien + immer
// Goslar/MeinGoslar/UnserKlüngelKannMehr), fuer bereits veroeffentlichte Posts,
// die vor dem Tag-Fix (2026-07-27) erstellt wurden.
// Nutzer-Korrektur (2026-07-27): betrifft auch Entwuerfe, nicht nur bereits
// veroeffentlichte Posts - jede Zeile mit wordpressGoslarDraftId braucht Tags,
// unabhaengig vom Veroeffentlichungsstatus (WordPress erlaubt Tag-Updates auch
// auf Drafts).

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function uniqueTags(tags) {
  return Array.from(new Set(tags.map(t => safeStr(t)).filter(Boolean).filter(t => t.length <= 50)));
}
function topicTagsFromText(text) {
  const t = String(text || '').toLowerCase();
  const tags = [];
  function hasAny(words) { return words.some(w => t.indexOf(String(w).toLowerCase()) !== -1); }
  if (hasAny(['bus','stadtbus','linie','liniennetz','haltestelle','oepnv','öpnv','fahrplan','verkehr','umleitung','sperrung','radweg','parkplatz'])) tags.push('Verkehr','ÖPNV');
  if (hasAny(['bauschutt','baustelle','bauzaun','abbruch','abriss','baustellensicherheit','absperrung'])) tags.push('Baustelle','Sicherheit');
  if (hasAny(['stadtbus','haltestelle','fahrgast','fahrgäste','linienfuehrung','schuljahresbeginn'])) tags.push('Stadtbus');
  if (hasAny(['denkmalschutz','altstadt','unesco','welterbe','denkmal','sanierung','historisch'])) tags.push('Altstadt','Denkmalschutz','UNESCO');
  if (hasAny(['haushalt','kosten','finanz','haushaltsmittel','foerderung','investition','gebühr','zuschuss'])) tags.push('Haushalt','Finanzen','Kosten');
  if (hasAny(['schule','schüler','schülerinnen','kita','kindergarten','bildung','jugend','schulweg'])) tags.push('Schule','Bildung');
  if (hasAny(['mülleimer','papierkorb','abfall','bänke','bank','sitzbank','stadtbild','aufenthaltsqualität','innenstadt','standort'])) tags.push('Stadtbild','Aufenthaltsqualität');
  if (hasAny(['digitalisierung','software','open source','verwaltung','transparenz','daten','portal','online','it'])) tags.push('Verwaltung','Digitalisierung','Transparenz');
  if (hasAny(['energie','wärme','wärmeplanung','klima','klimaschutz','heizung','wärmenetz','fernwärme'])) tags.push('Energie','Wärmeplanung','Klimaschutz');
  if (hasAny(['barriere','barrierefreiheit','inklusion','teilhabe','behinderung','senioren','ältere menschen'])) tags.push('Barrierefreiheit','Inklusion');
  if (hasAny(['wahl','wahlwerbung','plakat','plakate','sondernutzung','wahlvorschlag','kandidierende','einzelbewerbung','chancengleichheit'])) tags.push('Wahl','Wahlwerbung','Chancengleichheit');
  return tags;
}
const ALWAYS_TAGS = ['Goslar', 'MeinGoslar', 'UnserKlüngelKannMehr'];

const rows = $input.all().map(i => i.json || {});
const targets = [];
for (const r of rows) {
  const postId = safeStr(r.wordpressGoslarPostId) || safeStr(r.wordpressGoslarDraftId);
  if (!postId) continue;
  const title = safeStr(r.websiteHeadline) || (safeStr(r.vorgangsnummer) + ' - ' + safeStr(r.title));
  const combinedTagText = [title, r.vorgangsnummer, r.thema, r.betroffene, r.kostenHaushalt, r.buergerwirkung, r.websiteArticle].map(safeStr).join(' ');
  const wpTags = uniqueTags([...ALWAYS_TAGS, ...topicTagsFromText(combinedTagText)]);
  targets.push({ vorgangsnummer: safeStr(r.vorgangsnummer), postId, wpTags });
}

const allNeededTagNames = uniqueTags(targets.flatMap(t => t.wpTags));

return [{ json: { targets, allNeededTagNames } }];

const current = $('Berechne Tags je Ziel-Post').first().json;
const allNeededTagNames = Array.isArray(current.allNeededTagNames) ? current.allNeededTagNames : [];

function norm(v) { return String(v || '').trim().toLowerCase(); }

const rawExisting = $input.all().map(i => i.json);
let existingList = rawExisting;
if (rawExisting.length === 1 && Array.isArray(rawExisting[0])) {
  existingList = rawExisting[0];
}

const existingByName = new Map();
for (const t of existingList) {
  if (t && t.name) existingByName.set(norm(t.name), t.id);
}

const resolvedByName = {};
const missingTagNames = [];
for (const name of allNeededTagNames) {
  const n = norm(name);
  if (existingByName.has(n)) resolvedByName[name] = existingByName.get(n);
  else missingTagNames.push(name);
}

return [{ json: { ...current, resolvedByName, missingTagNames } }];

const current = $input.first().json;
const missing = Array.isArray(current.missingTagNames) ? current.missingTagNames : [];

if (missing.length === 0) {
  return [{ json: { tagName: '', isSentinel: true } }];
}

return missing.map(name => ({ json: { tagName: name, isSentinel: false } }));

const original = $('Ermittle fehlende Tags (Backfill)').first().json;
const resolvedByName = original.resolvedByName || {};

function extractTagResult(j) {
  if (!j) return null;
  if (j.id && j.name) return { id: j.id, name: j.name };
  if (j.error && j.error.data && j.error.data.term_id) return { id: j.error.data.term_id, name: null };
  return null;
}

const createdByName = { ...resolvedByName };
for (const item of $input.all()) {
  const r = extractTagResult(item.json || {});
  if (r && r.name) createdByName[r.name] = r.id;
}

// Falls ein term_exists-Fallback ohne Namen kam, ordnen wir ihn ueber die Split-Reihenfolge zu.
const splitItems = $('Split fehlende Tags').all().map(i => i.json);
$input.all().forEach((item, idx) => {
  const r = extractTagResult(item.json || {});
  if (r && !r.name && splitItems[idx] && splitItems[idx].tagName) {
    createdByName[splitItems[idx].tagName] = r.id;
  }
});

const targets = Array.isArray(original.targets) ? original.targets : [];
const updates = targets.map(t => ({
  postId: t.postId,
  vorgangsnummer: t.vorgangsnummer,
  tagIds: [...new Set(t.wpTags.map(name => createdByName[name]).filter(Boolean))]
}));

return updates.map(u => ({ json: u }));
